class Report(BaseDocTemplate):
    def __init__(self, filename):
        super().__init__(str(filename), pagesize=A4, rightMargin=18*mm, leftMargin=18*mm, topMargin=19*mm, bottomMargin=17*mm, title='Laboratorio 09 - MuroCampus', author='Jesús Castillo Sumire')
        frame = Frame(self.leftMargin, self.bottomMargin, self.width, self.height, leftPadding=0, rightPadding=0, topPadding=0, bottomPadding=0)
        self.addPageTemplates(PageTemplate(id='main', frames=frame, onPage=self.draw_page))
    def draw_page(self, canvas, doc):
        canvas.saveState(); w,h=A4
        if doc.page == 1:
            canvas.setFillColor(BLUE); canvas.rect(0,h-12*mm,w,12*mm,stroke=0,fill=1)
        else:
            canvas.setStrokeColor(colors.HexColor('#DCE4EC')); canvas.setLineWidth(.6); canvas.line(18*mm,h-12*mm,w-18*mm,h-12*mm)
            canvas.setFont('Arial-Bold',8); canvas.setFillColor(BLUE); canvas.drawString(18*mm,h-9*mm,'MUROCAMPUS  /  LABORATORIO 09')
        canvas.setStrokeColor(colors.HexColor('#DCE4EC')); canvas.line(18*mm,12*mm,w-18*mm,12*mm)
        canvas.setFont('Arial',8); canvas.setFillColor(MUTED); canvas.drawString(18*mm,8*mm,'Programación en Móviles  ·  Jesús Castillo Sumire  ·  C24D'); canvas.drawRightString(w-18*mm,8*mm,str(doc.page)); canvas.restoreState()

styles=getSampleStyleSheet()
