def P(t,s='BodyX'): return Paragraph(t,styles[s])
def code(label,path,snippet):
    cs=ParagraphStyle(name='Code',fontName='Consolas',fontSize=7.2,leading=9.3,textColor=INK,backColor=PALE,borderColor=colors.HexColor('#D7E3ED'),borderWidth=.5,borderPadding=7)
    return Table([[P(label,'CodeLabel')],[Preformatted(snippet.strip('\n'),cs)],[P('Ubicación: <font name="Consolas">'+path+'</font>','SmallX')]],colWidths=[174*mm],style=TableStyle([('LEFTPADDING',(0,0),(-1,-1),0),('RIGHTPADDING',(0,0),(-1,-1),0),('TOPPADDING',(0,0),(-1,-1),2),('BOTTOMPADDING',(0,0),(-1,-1),3)]))
def shot(name,caption,width=100*mm):
    im=Image(str(EVID/name)); im._restrictSize(width,152*mm); im.hAlign='CENTER'; return [im,Spacer(1,3),P(caption,'SmallX')]
def table(rows,widths):
    t=Table(rows,colWidths=widths,repeatRows=1)
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),BLUE),('GRID',(0,0),(-1,-1),.4,colors.HexColor('#D5DFE8')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)])); return t

story=[]
cover=Table([[P('INFORME DE LABORATORIO','CoverSmall')],[Spacer(1,12*mm)],[P('MuroCampus','TitleX')],[P('Consumo de servicios REST en Android con Kotlin y Jetpack Compose','SubX')],[Spacer(1,12*mm)],[P('Laboratorio 09 actualizado  ·  Semana 09','CoverSmall')],[P('Estudiante: Jesús Castillo Sumire  ·  Sección C24D','CoverSmall')],[P('Curso: Programación en Móviles  ·  Docente: J. Leons','CoverSmall')],[Spacer(1,8*mm)],[P('Guía de funcionamiento, arquitectura, evidencias y código explicado','CoverSmall')]],colWidths=[174*mm],style=TableStyle([('BACKGROUND',(0,0),(-1,-1),BLUE),('LEFTPADDING',(0,0),(-1,-1),14*mm),('RIGHTPADDING',(0,0),(-1,-1),14*mm),('TOPPADDING',(0,0),(-1,-1),7*mm),('BOTTOMPADDING',(0,0),(-1,-1),7*mm)]))
story += [Spacer(1,33*mm),cover,Spacer(1,13*mm),P('Este informe reúne las dos variantes del trabajo en un solo documento. Las pantallas exigidas se muestran primero desde la versión base; al final se explica la búsqueda local añadida en mejora-ia. El propósito es seguir el recorrido del dato desde la API hasta cada pantalla y explicar por qué se separaron las responsabilidades.'),P('Las capturas incluidas se tomaron del emulador. Los resultados de JSONPlaceholder son demostrativos: acepta las solicitudes de creación y eliminación, pero no conserva esos cambios como lo haría una base de datos real.','NoteX'),PageBreak()]

story += [P('1. Qué se construyó','H1X'),P('MuroCampus es una aplicación Android que consulta publicaciones de un servicio REST. El usuario puede recorrer el muro, filtrar por autor, abrir una publicación y leer sus comentarios, y enviar una nueva publicación desde un formulario. La interfaz presenta estados de carga, éxito y error, y permite volver a intentar una consulta cuando falla la conexión.'),P('La guía actualizada conserva las pantallas y el orden de interacción indicados por el docente. Se utilizó JSONPlaceholder porque ofrece endpoints de práctica para publicaciones y comentarios. No es un backend propio ni una base de datos persistente para esta aplicación.'),P('Flujo general','H2X'),table([[P('Acción en Compose','TableHeadX'),P('Coordinación','TableHeadX'),P('Acceso a datos','TableHeadX'),P('Respuesta','TableHeadX')],[P('Abrir muro, filtrar, ver detalle o enviar','TableX'),P('PostsViewModel inicia coroutines y actualiza StateFlow','TableX'),P('PostRepository llama a PostApi mediante Retrofit y OkHttp','TableX'),P('JSON convertido a modelos y mostrado como UiState','TableX')]], [42*mm,43*mm,48*mm,41*mm]),Spacer(1,5),P('La llamada se ejecuta fuera del hilo visual al ser una función suspendida iniciada desde viewModelScope. La pantalla observa el estado y se recompone cuando cambia; no realiza solicitudes directamente.','NoteX'),P('Alcance de las ramas','H2X'),P('main contiene la versión base solicitada para el laboratorio. mejora-ia contiene las mismas funciones base y agrega búsqueda local por título, una solicitud DELETE demostrativa y el encabezado Accept: application/json. Ambas ramas incluyen las capturas y los documentos de entrega.'),PageBreak()]

story += [P('2. Estructura y responsabilidad de archivos','H1X')]
tree='''MuroCampus/\n  app/src/main/java/com/tecsup/murocampus/\n    MainActivity.kt                 tema, ViewModel y navegación simple\n    model/Modelos.kt                Post, Comentario y NuevoPost\n    data/PostRepository.kt          contrato y manejo de errores\n    data/remote/PostApi.kt          endpoints HTTP de Retrofit\n    data/remote/RetrofitClient.kt   URL base, OkHttp y JSON\n    viewmodel/PostsViewModel.kt     operaciones y estado observable\n    viewmodel/PostsViewModelFactory.kt crea dependencias\n    viewmodel/UiState.kt            Cargando, Exito y Error\n    ui/PantallaLista.kt             muro y filtros de usuario\n    ui/PantallaDetalle.kt           publicación y comentarios\n    ui/PantallaCrear.kt             formulario de publicación\n    ui/Componentes.kt               tarjetas, carga y error\n    ui/theme/Theme.kt               colores Material 3'''
story += [Preformatted(tree,ParagraphStyle(name='Tree',fontName='Consolas',fontSize=8,leading=11,textColor=INK,backColor=PALE,borderColor=colors.HexColor('#D7E3ED'),borderWidth=.5,borderPadding=8)),Spacer(1,6),P('La interfaz (ui) conoce el ViewModel, pero no Retrofit. El ViewModel concentra los eventos del usuario y decide qué operación ejecutar. El Repository traduce excepciones a Result y evita que el resto de la app dependa de detalles HTTP. PostApi describe las rutas; Retrofit construye la implementación de esa interfaz.'),P('Recorrido del dato: 1. Una tarjeta o botón envía un evento al ViewModel. 2. El ViewModel lanza una solicitud con viewModelScope. 3. El Repository llama a PostApi. 4. Retrofit convierte JSON a modelos Kotlin. 5. El ViewModel publica UiState. 6. Compose observa StateFlow y dibuja la vista correspondiente.'),PageBreak()]

story += [P('3. Código importante, explicado','H1X'),P('Los fragmentos son extractos del código fuente. Se han acortado para centrar la explicación en la idea que conviene exponer.'),code('Modelos que representan JSON','model/Modelos.kt','''@Serializable\ndata class Post(\n    val userId: Int,\n    val id: Int,\n    val title: String,\n    val body: String\n)'''),P('@Serializable permite que Kotlin Serialization convierta el objeto JSON a Post y viceversa. Los nombres de propiedad coinciden con los campos de JSONPlaceholder. Comentario y NuevoPost representan comentarios recibidos y datos enviados al crear.'),code('Rutas del servicio','data/remote/PostApi.kt','''@GET("posts/{id}")\nsuspend fun detalle(@Path("id") id: Int): Post\n\n@GET("posts/{id}/comments")\nsuspend fun comentarios(@Path("id") id: Int): List<Comentario>\n\n@GET("posts")\nsuspend fun porUsuario(@Query("userId") userId: Int): List<Post>\n\n@POST("posts")\nsuspend fun crear(@Body nuevo: NuevoPost): Post'''),P('@Path reemplaza el segmento {id}; @Query agrega un parámetro a la URL; @Body serializa el objeto como cuerpo JSON de POST. Las funciones suspend permiten esperar la respuesta sin bloquear la interfaz.'),PageBreak()]

story += [code('Configuración de red y conversión','data/remote/RetrofitClient.kt','''private val json = Json { ignoreUnknownKeys = true }\n\nprivate val cliente = OkHttpClient.Builder()\n    .addInterceptor { chain ->\n        val request = chain.request().newBuilder()\n            .header("Accept", "application/json")\n            .build()\n        chain.proceed(request)\n    }.build()\n\nRetrofit.Builder()\n    .baseUrl("https://jsonplaceholder.typicode.com/")\n    .client(cliente)\n    .addConverterFactory(\n        json.asConverterFactory("application/json".toMediaType())\n    )'''),P('Retrofit combina la URL base con rutas como posts. OkHttp ejecuta la comunicación y el interceptor agrega Accept. El convertidor interpreta la respuesta JSON. ignoreUnknownKeys permite descartar campos adicionales; no evita errores si falta un dato obligatorio.'),code('Repository envuelve el resultado','data/PostRepository.kt','''private suspend fun <T> llamar(\n    bloque: suspend () -> T\n): Result<T> = try {\n    Result.success(bloque())\n} catch (e: CancellationException) {\n    throw e\n} catch (e: Exception) {\n    Result.failure(e)\n}'''),P('Result hace explícito el éxito o el error. CancellationException se relanza porque cancelar una pantalla o tarea es parte del control normal de coroutines; no debe mostrarse como fallo de conexión.'),PageBreak()]

story += [code('Detalle: dos consultas concurrentes','viewmodel/PostsViewModel.kt','''val datos = coroutineScope {\n    val post = async { repo.detalle(id).getOrThrow() }\n    val comentarios = async { repo.comentarios(id).getOrThrow() }\n    DetalleUi(post.await(), comentarios.await())\n}'''),P('El detalle necesita dos respuestas independientes. async inicia ambas tareas y await reúne los resultados. coroutineScope mantiene el trabajo agrupado: si una solicitud falla, el ViewModel publica el error correspondiente.'),code('Estado de interfaz','viewmodel/UiState.kt','''sealed interface UiState<out T> {\n    data object Cargando : UiState<Nothing>\n    data class Exito<T>(val datos: T) : UiState<T>\n    data class Error(val mensaje: String) : UiState<Nothing>\n}'''),P('Con estos tres estados, la pantalla sabe si hay una consulta activa, si recibió contenido o si falló. Un when en Compose muestra el indicador, el contenido o el error con botón de reintento.'),code('Observación del flujo en Compose','ui/PantallaLista.kt','''val estado by viewModel.lista.collectAsStateWithLifecycle()\n\nwhen (val actual = estado) {\n    UiState.Cargando -> Cargando()\n    is UiState.Error -> ErrorConReintento(\n        actual.mensaje, viewModel::cargar\n    )\n    is UiState.Exito -> MostrarPublicaciones(actual.datos)\n}'''),P('collectAsStateWithLifecycle observa StateFlow respetando el ciclo de vida. Cuando cambia el dato, Compose vuelve a dibujar la parte necesaria.'),PageBreak()]

story += [P('4. Evidencias de la versión base','H1X'),P('Estas cinco capturas documentan el recorrido principal solicitado: muro, detalle con comentarios, filtro, envío y manejo de desconexión.')]
for fn,cap in [('01_lista.png','Muro con publicaciones descargadas. Cada tarjeta identifica al autor y resume título y texto.'),('02_detalle_comentarios.png','Detalle de una publicación y comentarios asociados. El post y sus comentarios se solicitan por separado.'),('03_filtro_usuario.png','Filtro por usuario. El chip seleccionado restringe la consulta al userId correspondiente.'),('04_crear_publicacion.png','Formulario de creación. El servicio de práctica devuelve un identificador; el cambio no persiste.'),('05_error_conexion.png','Estado de error con una acción explícita para reintentar tras recuperar la conexión.')]:
    story += [P(cap.split('.')[0],'H2X')] + shot(fn,cap) + [Spacer(1,5)]

story += [PageBreak(),P('5. Flujo funcional y endpoints','H1X'),table([[P('Acción','TableHeadX'),P('Método y ruta','TableHeadX'),P('Uso en la app','TableHeadX')],[P('Listar','TableX'),P('GET /posts','TableX'),P('Carga los 100 registros del muro.','TableX')],[P('Detalle','TableX'),P('GET /posts/{id}','TableX'),P('Trae los datos de una publicación.','TableX')],[P('Comentarios','TableX'),P('GET /posts/{id}/comments','TableX'),P('Trae comentarios de la publicación.','TableX')],[P('Filtrar autor','TableX'),P('GET /posts?userId={id}','TableX'),P('Limita el muro al usuario elegido.','TableX')],[P('Crear','TableX'),P('POST /posts','TableX'),P('Envía userId, title y body como JSON.','TableX')],[P('Eliminar, mejora-ia','TableX'),P('DELETE /posts/{id}','TableX'),P('Demostración; no elimina persistentemente.','TableX')]], [34*mm,54*mm,86*mm]),Spacer(1,8),P('Importante al sustentar','H2X'),P('La app no guarda posts en Firebase ni en una base local. JSONPlaceholder devuelve una respuesta de ejemplo para POST y DELETE, pero la lista original permanece igual después de recargar. Para persistencia real haría falta un backend con almacenamiento.','NoteX'),P('IOException se presenta como problema de conexión; HttpException permite mostrar el código HTTP; SerializationException señala que la respuesta no coincide con los modelos. Reintentar vuelve a ejecutar la operación desde el ViewModel.'),PageBreak()]

story += [P('6. Rama mejora-ia','H1X'),P('La versión mejorada conserva el flujo base y agrega búsqueda local por título. La lista se filtra en memoria sobre los resultados ya descargados: escribir no provoca una solicitud HTTP por cada tecla.'),P('También incorpora una opción DELETE demostrativa en detalle y el encabezado Accept: application/json en OkHttp. La interfaz aclara que eliminación y creación no son persistentes en el servicio de práctica.'),P('Búsqueda local agregada','H2X')] + shot('06_mejora_ia_busqueda.png','Captura de mejora-ia con búsqueda y publicaciones coincidentes.',105*mm) + [Spacer(1,5),code('Filtrado local del título','ui/PantallaLista.kt (mejora-ia)','''val coincidencias = actual.datos.filter {\n    it.title.contains(busqueda, ignoreCase = true)\n}'''),P('Se compara el texto con title sin distinguir mayúsculas y minúsculas. La búsqueda usa los posts ya presentes en UiState.Exito; no genera una petición por carácter.'),PageBreak(),P('Paleta por usuario','H1X'),P('La tarjeta identifica visualmente al autor con una etiqueta de color, siguiendo la referencia que enviaste. Cada userId usa un color estable; sobre amarillo se usa texto oscuro para mantener contraste. El ajuste se incorporó en ambas ramas y ambas compilan correctamente con Gradle.'),P('Evidencia pendiente de captura','H2X'),P('La versión con colores se compiló correctamente en main y mejora-ia. No se pudo instalarla ni sacar una captura nueva porque ADB no encontró conectado el emulador Pixel 8. Por eso, las capturas del informe documentan las pantallas anteriores al último ajuste de color; el código actualizado sí está incluido, pero su apariencia en ejecución queda pendiente de una captura manual en Android Studio.','NoteX'),PageBreak()]

story += [P('7. Comprobaciones y límites','H1X'),P('Este cuadro refleja el registro disponible. “Pendiente” significa que el escenario no se ejecutó; no debe presentarse como aprobado.')]
story += [table([[P('Caso','TableHeadX'),P('Estado','TableHeadX'),P('Qué demuestra','TableHeadX')],[P('Lista, detalle y comentarios','TableX'),P('Aprobado','TableX'),P('Consultas REST de lectura.','TableX')],[P('Filtro de usuario y lista general','TableX'),P('Aprobado','TableX'),P('Consulta userId y retorno a todos.','TableX')],[P('POST de publicación','TableX'),P('Aprobado','TableX'),P('Respuesta 101 observada; no persistente.','TableX')],[P('Desconexión y reintento','TableX'),P('Aprobado','TableX'),P('Error visible y recuperación de consulta.','TableX')],[P('404 de publicación','TableX'),P('Pendiente','TableX'),P('Falta provocar y capturar el HTTP 404.','TableX')],[P('JSON adicional o incompleto','TableX'),P('Parcial','TableX'),P('Configuración revisada; faltó modificar respuesta.','TableX')],[P('Cancelación durante solicitud lenta','TableX'),P('Pendiente','TableX'),P('Código revisado; falta reproducir y capturar.','TableX')],[P('Compilación tras cambio de paleta','TableX'),P('Aprobado','TableX'),P('Gradle compiló main y mejora-ia.','TableX')],[P('Captura nueva de paleta','TableX'),P('Pendiente','TableX'),P('ADB no detectó el emulador Pixel 8.','TableX')]], [52*mm,34*mm,88*mm]),Spacer(1,8),P('Preguntas que pueden aparecer','H2X'),P('¿Por qué hay Repository? Para separar acceso a datos del ViewModel y permitir cambiar la fuente. ¿Qué hace Retrofit? Implementa PostApi y convierte JSON. ¿Para qué StateFlow? Mantiene y expone estado observable. ¿POST guarda el post? No; el servicio de práctica devuelve una respuesta simulada. ¿Qué ocurre sin Internet? El error llega al Repository y el ViewModel lo transforma en UiState.Error.'),P('Conclusión','H2X'),P('En este laboratorio practiqué cómo una app Android consume endpoints REST y presenta sus resultados sin mezclar la interfaz con el código de red. La separación entre modelos, API, Repository, ViewModel y pantallas permite seguir el camino de cada dato y ubicar cada responsabilidad. La práctica también deja clara una limitación: recibir una respuesta satisfactoria de un servicio de demostración no equivale a guardar información de manera permanente. Antes de sustentar, repetiré en el emulador la comprobación visual de la paleta y los casos de aceptación pendientes.'),P('Fuentes: guía actualizada GLAB-S09-JLEONS-2026-2, código de Semana_09/MuroCampus y EVIDENCIAS.md. Las capturas se tomaron de ejecuciones documentadas en el emulador.','SmallX')]

Report(OUT).build(story)
print(OUT)
